        if opp_coop_rate < 0.4:
            return 'D'
        return 'D'

    # Early game: establish cooperation, but avoid being exploited
    if n < 4:
        return 'C'

    # If opponent just defected on our cooperation, respond with punishment, but forgive after a while
    if opp_last == 'D' and my_last == 'C':
        # They exploited us. Defect for a couple rounds.
        return 'D'

    # If opponent just cooperated after we defected, reward with cooperation
    if opp_last == 'C' and my_last == 'D':
        # But if they seem exploitative overall, keep defecting
        if opp_coop_rate > 0.5:
            return 'C'
        return 'D'

    # Both same action
    if opp_last == 'C' and my_last == 'C':
        # Mutual cooperation is great; continue unless opponent shows signs of defection
